public interface IShape                        // contract: no instance state
{
    double Area();
    string Describe() => $"area {Area():F2}";  // default member (C# 8)
}

public sealed class Square : IShape
{
    private readonly double _side;            // state belongs to the implementation
    public Square(double side) => _side = side;
    public double Area() => _side * _side;
}
